VAR
    SensorFault        : BOOL;
    HeatingRequested   : BOOL;
    HeaterCmd          : BOOL;   // internal command before output
    OverheatTimer      : TON;
    OverheatWaitTimer  : TON;
END_VAR

// 1. Sensor fault detection
