    OverheatProtection := FALSE;
END_IF;

// 8. Compute final heater command using the updated OverheatProtection
HeaterCmd := HeatingRequested AND NOT OverheatProtection;

// 9. Assign heater output
HeaterOutput := HeaterCmd;

// 10. Status outputs
CurrentTemperature := TemperatureSensorInput;
SetTempDisplay     := SetTemperature;
HeaterStatus       := HeaterOutput;

END_FUNCTION_BLOCK
